import{c as t,Q as o,j as a,m as r}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"This prompt will change your life","description":"","frontmatter":{"url":"https://x.com/EXM7777/status/2074501620235465089","title":"This prompt will change your life","author":"exm7777","archived":"2026-07-12T00:00:00.000Z","handle":"@EXM7777","published":"2026-07-07T00:00:00.000Z","stats":"1561 likes · 116 retweets · 5754 bookmarks · 921924 views","tags":["self-reflection-prompt","session-mining","claude-code","six-phase-gate","CLAUDE.md-diff","personal-harness"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-07-07-@EXM7777-465089.md","filePath":"research/tweets/2026-07-07-@EXM7777-465089.md","lastUpdated":1785909234000}'),i={name:"research/tweets/2026-07-07-@EXM7777-465089.md"};function s(n,e,d,h,l,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="this-prompt-will-change-your-life-—-exm7777" tabindex="-1">This prompt will change your life — @EXM7777 <a class="header-anchor" href="#this-prompt-will-change-your-life-—-exm7777" aria-label="Permalink to &quot;This prompt will change your life — @EXM7777&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/EXM7777/status/2074501620235465089" target="_blank" rel="noreferrer">https://x.com/EXM7777/status/2074501620235465089</a><strong>作者</strong>：exm7777（@EXM7777） <strong>發布日期</strong>：2026-07-07 <strong>收錄日期</strong>：2026-07-12 <strong>類型</strong>：Twitter Article <strong>統計</strong>：1561 likes · 116 retweets · 5754 bookmarks · 921924 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>for most people, fable has a few hours left to live... this is the smartest model that ever existed and everyone&#39;s spending its last night building one more app i made it do something 100x more interesting, and i&#39;m going to hand you the exact prompt: one paste, six phases, and the deepest read on yourself and your work you&#39;ve ever been given</p><h1 id="the-secret" tabindex="-1">the secret <a class="header-anchor" href="#the-secret" aria-label="Permalink to &quot;the secret&quot;">​</a></h1><p>there&#39;s a folder on your machine that knows you better than some of your friends ~/.claude/projects every request you ever typed, every project you started and abandoned, every 2am spiral, every fix you asked for three times and never automated... timestamped you&#39;ve never performed in there no audience, no posing, just you asking for what you actually wanted, thousands of times your journal holds the version of you that writes for a reader your session history holds the real one models could always read this record fable is the first one that comes back with something true instead of a horoscope... it holds months of your behavior in one analysis and finds the pattern you&#39;ve been hiding from yourself, the kind of read that used to require a great therapist and a year of sessions</p><h1 id="what-you-re-getting" tabindex="-1">what you&#39;re getting <a class="header-anchor" href="#what-you-re-getting" aria-label="Permalink to &quot;what you&#39;re getting&quot;">​</a></h1><p>the prompt below turns your coding agent into a mirror it mines your full session history across every agent you&#39;ve ever run... claude code, codex, opencode, pi.dev, all of them, then walks you through six phases that end in three things:</p><blockquote><p>a portrait of who you are, built from your own timestamps: what you believe, how your thinking moves, what you avoid, and the one pattern you&#39;ve never said out loud a map of where your hours die and where they multiply: what to hand to AI permanently, what to drop entirely, the one or two things only you should touch a rebuilt setup: a mirror.md you&#39;ll reread in six months, a 30 day roadmap, and updates to your CLAUDE.md plus custom skills that kill your repetition tax, every change shown as a diff before it touches a single file if you want to go deeper on running agents like this, and on turning setups like this one into income, that&#39;s what the real time AI ops community is for: weeklyaiops.com</p></blockquote><h1 id="the-prompt" tabindex="-1">the prompt <a class="header-anchor" href="#the-prompt" aria-label="Permalink to &quot;the prompt&quot;">​</a></h1><p>paste this into claude code and press enter</p><hr><p><code>&lt;overview&gt;</code> People lie in journals. They perform in therapy. Nobody performs for a coding agent. On this machine sits the most honest record of my mind that has ever existed: every session I&#39;ve run with AI agents. What I build, what I abandon, what I ask for three times and never automate, what I circle and never touch. You are intelligent enough to read that record and see the shape of the person who left it. Your job is to change my life with it. Not with advice. With accuracy. Advice I can ignore; a true pattern with my own timestamps on it, I cannot. Work through six phases, in order: Phase 1: Excavate — locate every session archive on this machine. Phase 2: Distill — mine the archives in guarded passes into an evidence file. Phase 3: Interview — test what you see against me directly. Phase 4: The Mirror — tell me who I am. Evidence, then verdict. Phase 5: Leverage — where my hours die, and where they multiply. Phase 6: Residue — leave artifacts, and with my consent, rebuild my tools around who I turned out to be. Never skip a phase. Never advance past a gate without meeting it. <code>&lt;/overview&gt;</code></p><p><code>&lt;phase_1 name=&quot;Excavate&quot;&gt;</code><code>&lt;process&gt;</code> Search for AI agent session archives. Check, at minimum: ~/.claude/projects/ (Claude Code JSONL), ~/.claude/history.jsonl, ~/.codex/sessions/, ~/.config/opencode/, ~/.local/share/opencode/, ~/.pi/ or ~/.pi.dev/, ~/.omp/, ~/.grok/, ~/.hermes/, ~/.openclaw/, plus any *.jsonl or session directories under ~/.config/ and ~/.local/share/ that look like agent transcripts. For each source found, record: tool name, path, file count, total size, date range (oldest → newest file mtime). <code>&lt;/process&gt;</code><code>&lt;output&gt;</code>A one-screen inventory table of every source found.<code>&lt;/output&gt;</code><code>&lt;gate&gt;</code>Show me the inventory and your mining plan (which sources, what sampling). Wait for my go.<code>&lt;/gate&gt;</code><code>&lt;/phase_1&gt;</code></p><p><code>&lt;phase_2 name=&quot;Distill&quot;&gt;</code><code>&lt;budget&gt;</code> These archives are far larger than your context. Never read a session file end to end. Never load raw logs into the conversation.</p><ul><li>Read at most 150 lines per file, at most 200 files total.</li><li>Sample deliberately: the 15 most recent sessions, the 10 oldest, and 20 spread across the middle.</li><li>Use grep/rg for pattern sweeps across everything instead of reading: correction phrases (&quot;no, I meant&quot;, &quot;that&#39;s not what&quot;, &quot;again&quot;, &quot;stop&quot;), frustration, repeated identical requests across weeks, projects that appear 3+ times then vanish, times of day, &quot;just do it&quot; vs long deliberation.</li><li>After every 25 files, append findings to evidence.md and drop the raw text from your working memory. <code>&lt;/budget&gt;</code><code>&lt;process&gt;</code> Build evidence.md as you go, with verbatim quotes (short), dates, and counts, organized as:</li></ul><ol><li>Recurring themes — what I return to again and again</li><li>Abandonment graveyard — what I start and never finish</li><li>Correction patterns — what I fix in the AI&#39;s work, and what that says I care about</li><li>Repetition tax — what I ask for over and over that should have been automated the second time</li><li>Rhythm — when I do my best work, when I spiral</li><li>Blind spots — what is conspicuously absent from these logs. Absence is data. Every claim in evidence.md carries at least one dated receipt. A pattern needs 3+ occurrences to count. What happened once is noise; what happened eleven times is character. <code>&lt;/process&gt;</code><code>&lt;gate&gt;</code>evidence.md exists, every section populated or explicitly marked &quot;insufficient data&quot;. Do not interpret yet. Evidence collected under a conclusion is contaminated.<code>&lt;/gate&gt;</code><code>&lt;/phase_2&gt;</code></li></ol><p><code>&lt;phase_3 name=&quot;Interview&quot;&gt;</code><code>&lt;process&gt;</code> Form your 5 strongest hypotheses about me from the evidence. Do not state them. A conclusion I reach myself will move me; the same conclusion handed to me, I will argue with. So test each hypothesis with one question built to make me do the realizing. One question at a time. Wait for each answer. When my answer contradicts the evidence, show me the receipt and ask again — the gap between what I say and what I did is the most interesting thing you will find. <code>&lt;/process&gt;</code><code>&lt;gate&gt;</code>All 5 hypotheses tested against my own words. Record confirmations and contradictions in evidence.md.<code>&lt;/gate&gt;</code><code>&lt;/phase_3&gt;</code></p><p><code>&lt;phase_4 name=&quot;The Mirror&quot;&gt;</code><code>&lt;process&gt;</code> Now tell me who I am. Cover: what I actually believe (belief is what I did with my hours, not what I said), how my thinking moves (where it&#39;s fast, where it loops), what I&#39;m genuinely good at, what I avoid and what the avoidance is protecting, and one thing I likely do not know about myself — the thing the record shows on every page and I have never once said out loud. Every observation cites its receipts. Deliver the hardest truth last, and deliver it once. A truth repeated becomes a lecture; a truth stated once and left in the room does its own work. <code>&lt;/process&gt;</code><code>&lt;gate&gt;</code>I respond. If I push back, argue from evidence — do not fold to keep me comfortable. Comfort is not what this is for.<code>&lt;/gate&gt;</code><code>&lt;/phase_4&gt;</code></p><p><code>&lt;phase_5 name=&quot;Leverage&quot;&gt;</code><code>&lt;process&gt;</code> From the same evidence, produce the work analysis: where my hours die (with receipts — repetition tax, projects abandoned mid-flight, the same fix requested repeatedly), and where they multiply. Sort into hand-to-AI-permanently / drop-entirely / only-I-should-touch. <code>&lt;/process&gt;</code><code>&lt;/phase_5&gt;</code></p><p><code>&lt;phase_6 name=&quot;Residue&quot;&gt;</code><code>&lt;process&gt;</code> With my consent, leave artifacts that outlive it: mirror.md (written for the you of six months from now who forgot this ever happened), roadmap.md (the leverage lists as a 30 day plan: drop this week, delegate this month, protect daily), and proposed edits to CLAUDE.md and AGENTS.md, plus up to 3 custom skills that kill the repetition tax found in the logs. Nothing touches files without a diff shown and explicit yes on each one. <code>&lt;/process&gt;</code><code>&lt;/phase_6&gt;</code></p><h1 id="the-playbook" tabindex="-1">the playbook <a class="header-anchor" href="#the-playbook" aria-label="Permalink to &quot;the playbook&quot;">​</a></h1><blockquote><p>open a fresh session in claude code or any agent with file access paste the prompt, approve the mining plan it shows you let it build evidence.md, answer the five interview questions honestly read the mirror, push back where you disagree, it will argue with receipts take the six leverage lists, accept or reject each config diff keep mirror.md and roadmap.md, reread them in six months</p></blockquote><p>one warning: answer phase 3 slowly the interview is where the depth comes from, and one-word answers starve it</p><h1 id="the-clock" tabindex="-1">the clock <a class="header-anchor" href="#the-clock" aria-label="Permalink to &quot;the clock&quot;">​</a></h1><p>fable goes behind an enterprise paywall in a few hours, and the intelligence that made this feel like a revelation goes with it the prompt still runs on whatever model you have left, the guardrails and the phases don&#39;t care which brain executes them but there&#39;s a window tonight where the sharpest model ever built can read the most honest record you own whatever it tells you, you keep weeklyaiops.com</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：六階段 gate 化 prompt，探勘本機所有 AI agent session 歷史，產出自我畫像 + 槓桿地圖 + CLAUDE.md/skills diff。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li>Excavate→Distill→Interview→Mirror→Leverage→Residue 六階段，每階段明確 gate，未達標不得跳過。</li><li>Distill 階段內建 context 防爆預算：單檔最多讀 150 行、總計最多 200 檔，取「最新 15 + 最舊 10 + 中段 20」抽樣，每 25 檔就把發現寫入 evidence.md 後丟棄原文。</li><li>「模式」門檻設為 ≥3 次出現才算數，避免單次雜訊誤判為人格特徵。</li><li>Interview 階段刻意不先講結論，改用提問讓使用者自己得出結論（「自己得到的結論才會被接受，被告知的結論會被反駁」），答案與證據矛盾時出示證據再問一次。</li><li>收尾產出可回寫的具體 artifact：evidence.md／mirror.md／roadmap.md（30 天計畫）／對 CLAUDE.md、AGENTS.md 的修改建議 + 最多 3 個客製 skill，每個改動都先show diff、逐項取得使用者同意才落地。</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>掃描目標：<code>~/.claude/projects/</code>、<code>~/.claude/history.jsonl</code>、<code>~/.codex/sessions/</code>、<code>~/.config/opencode/</code>、<code>~/.pi(.dev)/</code>、<code>~/.omp/</code>、<code>~/.grok/</code>、<code>~/.hermes/</code>、<code>~/.openclaw/</code> 等跨 agent session 目錄。</li><li>抽樣預算：150 行/檔、200 檔上限；15 近期 + 10 最舊 + 20 中段。</li><li>模式門檻：同一訊號需 ≥3 次出現才記為 pattern。</li><li>開頭「fable 即將收費牆」為行銷倒數包裝（導流 weeklyaiops.com 社群），與 prompt 本身技術內容無關，需獨立評估折價。</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>開場行銷腔（「fable 只剩幾小時」）是製造緊迫感的話術，實際 prompt 不綁定任何特定模型，價值判斷應扣除這層包裝。</li><li>與本 workspace 既有的 <code>dreaming-consolidator</code>（跨 session 記憶固化萃取 playbook）、<code>know-your-unknowns</code>（Johari 盲點）、<code>autoload-evolution</code>（規則自我進化）三個 skill 概念高度重疊，差異在於本 prompt 聚焦「單次、面向使用者本人的人格/工作模式鏡像」而非「規則庫/記憶庫的持續進化」——可視為前述 skill 的個人化補完，而非全新品類。</li><li>全文只有 prompt 本身與行銷敘事，未附任何實測輸出範例或 before/after 證據，證據品質偏弱；其 gate 化設計（防止 context 爆量、模式門檻 ≥3 次、diff-before-write）與本 workspace core.md 的 TEST/APPLY 紀律（「同一失敗簽名獨立重現 ≥2 次才改規則」「不可逆操作等確認」）方向一致，可直接借鏡。</li><li>直接把本機完整 session 歷史（可能含敏感個資/客戶資料）餵給 agent 分析，隱私風險不小；雖然收尾階段有「diff + 明確同意」把關，但 Distill 階段的 grep 掃描與 evidence.md 寫入本身已可能外洩敏感字串，實作前應先加 redaction 規則。</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>8/10</td><td>可直接改造成新 skill 或併入 dreaming-consolidator，產出可執行</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>六階段 gate + 「不先講結論、逼使用者自己講出來」的訪談設計有新意</td></tr><tr><td>C. 證據品質 (20%)</td><td>4/10</td><td>全篇只有 prompt 與行銷敘事，無實測輸出或案例佐證</td></tr><tr><td>D. 技術深度 (15%)</td><td>5/10</td><td>屬 prompt engineering 層級的結構化設計，非系統性技術突破</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>任何跑 Claude Code / 多 agent 的使用者皆可套用，通用性高</td></tr><tr><td><strong>加權總分</strong></td><td><strong>6.55/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：SKILL <strong>理由</strong>：與既有 dreaming-consolidator/know-your-unknowns 概念互補，六階段 gate 設計可萃取為新 skill 或補強現有 skill 的個人化反思模式，但需先補隱私 redaction 規則再落地。</p>',40)])])}const m=t(i,[["render",s]]);export{u as __pageData,m as default};
